style.css:
@-moz-document domain("youtube.com") {
/*=====================================
      YouTube Dark & Red UI V2
======================================*/

:root{

/* Background */
--yt-spec-base-background:#000!important;
--yt-spec-raised-background:#0d0d0d!important;
--yt-spec-menu-background:#111!important;
--yt-spec-additive-background:#181818!important;

/* Text */
--yt-spec-text-primary:#fff!important;
--yt-spec-text-secondary:#b5b5b5!important;

/* Accent */
--yt-spec-static-brand-red:#ff2d2d!important;
--yt-spec-call-to-action:#ff2d2d!important;

/* Radius */
--radius:12px;

}

/* ---------- Global ---------- */

html,
body,
ytd-app{
    background:#000!important;
    color:#fff!important;
}

/* ---------- Header ---------- */

ytd-masthead{
    background:#000!important;
    border-bottom:1px solid #1d1d1d!important;
}

/* ---------- Sidebar ---------- */

#guide-content,
ytd-mini-guide-renderer{
    background:#000!important;
}

/* ---------- Search ---------- */

#container.ytd-searchbox{
    background:#111!important;
    border:1px solid #2a2a2a!important;
    border-radius:999px!important;
}

#container.ytd-searchbox:hover,
#container.ytd-searchbox:focus-within{
    border-color:#ff2d2d!important;
}

/* ---------- Buttons ---------- */

button,
yt-icon-button,
tp-yt-paper-button{
    color:#fff!important;
    transition:.18s;
}

button:hover,
yt-icon-button:hover,
tp-yt-paper-button:hover{
    color:#ff2d2d!important;
}

/* ---------- Subscribe ---------- */

ytd-subscribe-button-renderer button{
    background:#ff2d2d!important;
    color:#fff!important;
    border:none!important;
    border-radius:10px!important;
}

/* ---------- Cards ---------- */

ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer,
ytd-compact-video-renderer{
    background:#111!important;
    border-radius:12px!important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover{
    background:#181818!important;
}

/* ---------- Titles ---------- */

#video-title,
#title,
h1,
h2,
h3{
    color:#fff!important;
}

/* ---------- Links ---------- */

a{
    color:#ff2d2d!important;
}

a:hover{
    color:#ff6666!important;
}

/* ---------- Icons ---------- */

yt-icon,
svg{
    color:#fff!important;
    fill:currentColor!important;
}

/* Active icon */

[aria-selected="true"] yt-icon,
[aria-current="page"] yt-icon{
    color:#ff2d2d!important;
}

/* ---------- Progress ---------- */

.ytp-play-progress{
    background:#ff2d2d!important;
}

/* ---------- Inputs ---------- */

input,
textarea{
    color:#fff!important;
}

/* ---------- Scrollbar ---------- */

::-webkit-scrollbar{
    width:10px;
}

::-webkit-scrollbar-track{
    background:#000;
}

::-webkit-scrollbar-thumb{
    background:#333;
    border-radius:999px;
}

::-webkit-scrollbar-thumb:hover{
    background:#ff2d2d;
}
}
